# Edit a DRAFT claim: its amount, date (blank: the sheet's today) and note, validated as when added.
# Any other claim is refused (400) and writes nothing: to change an open claim, void it and add a new one.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# Change a claim's status: open (DRAFT -> OPEN), settle (OPEN -> SETTLED, or PENDING when a clerk settles
# above the clerk limit), approve (PENDING -> SETTLED), reject with a reason (PENDING -> OPEN) or void
# (DRAFT, OPEN or PENDING -> VOID; SETTLED -> VOID by a steward within 7 days of its settlement), or resettle (a steward refreezes a SETTLED claim at its figure today), or defer an
# OPEN claim (not in a closed period) until a date after the sheet's today (body: until).
# Or split an OPEN claim (body: amount; see ClaimSplit).
# Or redate: a steward re-dates an OPEN or PENDING claim (body: date; see ClaimRedate).
# Or lock / unlock: open or close the claim's editor, locking it for other users (see ClaimLock).
# Or proof: raise the proofs count of a claim not SETTLED or VOID (nor in a closed period) by one. Any other change is refused (400) and writes nothing.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: change
change:
  class: net.officefloor.hq.app.claim.ChangeClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveClaim {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            @Val ClaimInput input, ServerHttpConnection connection, ClaimRepository repository,
            SheetRepository sheets, PeriodRepository periods, PersonRepository people, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long cid;
        try {
            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such claim");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        // Only a draft can be edited: to change an open claim, void it and add a new one.
        if (!found.status().equals("DRAFT")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be edited");
        }
        String holder = repository.lockedBy(id, cid);
        if (holder != null && !holder.equals(by)) {
            throw new BadRequestException("the claim is being edited by " + holder);
        }
        LocalDate date = input.date() != null ? input.date() : sheets.today(id);
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        people.claimAllowed(id, found.personId(), date);
        input.checkCorrection(repository, id, found.personId());
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.update(id, cid, input.amount(), date, input.note(), input.corrects())) {
            throw new BadRequestException("only a DRAFT claim can be edited");
        }
        repository.unlock(id, cid, by);
        long pid = found.personId();
        Claim saved = new Claim(cid, pid, ClaimRepository.money(input.amount()), date.toString(), input.note(),
                found.status(), found.number(), found.due(), found.openedBy(), found.stated(), found.statedDue(), input.corrects(),
                found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded());
        audit.record("CLAIM_EDITED sheet=" + id + " by=" + by + " person=" + repository.personName(id, pid)
                + " amount=" + saved.amount() + " date=" + saved.date() + Claim.auditNumber(saved.number()));
        rollup.record(id, by, before);
        claim.set(saved);
    }
}
