18	function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
19	  const claims = useClaims(sheetId);
20	  const people = usePeople(sheetId);
21	  const today = useSheetToday(sheetId).data?.today;
22	  return (
23	    <td data-testid="person-claimed">
24	      {claimed((claims.data ?? []).filter((c) => c.personId === personId), holdsById(people.data, today), today)}
25	    </td>
26	  );
27	}
