29	type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle' | 'defer' | 'proof' | 'remind' | 'split' | 'redate';
30	
31	/** A claim's status changes; the server refuses one its status does not allow, a settle by the user
32	 *  who opened the claim, and an approve or reject by anyone but a steward (an approve also by the
33	 *  user who opened the claim), a re-settle by anyone but a steward or of a claim not SETTLED, and a void of a SETTLED claim by anyone but a steward, more than 7 days after its settlement or in a closed period. A reject takes the reason typed on the claim's row.
34	 *  A settle or approve of a claim whose due is above the proof threshold in force on its date is refused while it has no proof. */
35	const ACTIONS: [Exclude<ClaimAction, 'defer' | 'proof' | 'remind' | 'split' | 'redate'>, string][] = [
36	  ['open', 'Open'],
37	  ['settle', 'Settle'],
38	  ['approve', 'Approve'],
39	  ['reject', 'Reject'],
40	  ['void', 'Void'],
41	  ['resettle', 'Re-settle'],
42	];
43	
44	/** A person's claims, newest first, under their row, with a form that adds a claim, or edits one
45	 *  when its editor is open. A blank date takes the sheet's today. A negative amount is a correction:
46	 *  the form names, by number, the settled claim of the same person it corrects. */
47	function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
48	  const claims = useClaims(sheetId);
49	  const people = usePeople(sheetId);
50	  const rates = useRates(sheetId);
51	  const settings = useSettings(sheetId).data;
52	  const sheet = useSheetToday(sheetId).data;
53	  const today = sheet?.today;
54	  const periods = usePeriods(sheetId);
55	  const [user] = useSignedInUser();
56	  const queryClient = useQueryClient();
57	  const selection = useClaimSelection(sheetId);
58	  const [editing, setEditing] = useState<number | null>(null);
59	  const [refused, setRefused] = useState<{ id: number; message: string } | null>(null);
60	  const [amount, setAmount] = useState('');
61	  const [date, setDate] = useState('');
62	  const [note, setNote] = useState('');
63	  const [corrects, setCorrects] = useState('');
64	  const [reasons, setReasons] = useState<Record<number, string>>({});
65	  const [targets, setTargets] = useState<Record<number, string>>({});
66	  const [deferDates, setDeferDates] = useState<Record<number, string>>({});
67	  const [splitAmounts, setSplitAmounts] = useState<Record<number, string>>({});
68	  const [newDates, setNewDates] = useState<Record<number, string>>({});
69	
70	  const clearForm = () => {
71	    setEditing(null);
72	    setAmount('');
73	    setDate('');
74	    setNote('');
75	    setCorrects('');
76	  };
77	
78	  // Mark a claim's editor lock as held (or not) by this user in the cached list, ahead of the re-read.
79	  const markLock = (id: number, lockedBy: string | null) =>
80	    queryClient.setQueryData<Claim[]>(claimsKey(sheetId), (old) =>
81	      old?.map((c) => (c.id === id ? { ...c, lockedBy } : c)),
82	    );
83	
84	  const fillForm = (c: Claim) => {
85	    setEditing(c.id);
86	    setAmount(c.amount);
87	    setDate(c.date);
88	    setNote(c.note);
89	    setCorrects(c.corrects === null ? '' : String(c.corrects));
90	  };
91	
92	  const submitOnce = useSingleFlight();
93	  const save = useMutation({
94	    mutationFn: (f: { id: number | null; amount: string; date: string; note: string; corrects: string }) => {
95	      const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
96	      const path = f.id === null ? `${sheet}/people/${personId}/claims` : `${sheet}/claims/${f.id}`;
97	      return postJson<Claim>(path, { amount: f.amount, date: f.date, note: f.note, corrects: f.corrects });
98	    },
99	    onSuccess: async (_, f) => {
100	      if (f.id !== null) markLock(f.id, null);
101	      clearForm();
102	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
103	    },
104	  });
105	
106	  // Opening a claim's editor locks the claim for every other user until it is saved or cancelled (or the
107	  // sheet's today changes); the server refuses a claim another user holds, and any it would not let be edited.
108	  const lock = useMutation({
109	    mutationFn: (l: { id: number; action: 'lock' | 'unlock' }) =>
110	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${l.id}/${l.action}`, {}),
111	    onSuccess: (_, l) => {
112	      if (l.action === 'lock') {
113	        queryClient.setQueryData<Claim[]>(claimsKey(sheetId), (old) =>
114	          old?.map((c) =>
115	            c.id === l.id ? { ...c, lockedBy: user } : c.personId === personId && c.lockedBy === user ? { ...c, lockedBy: null } : c,
116	          ),
117	        );
118	      }
119	    },
120	  });
121	
122	  // A status change (open, settle, approve, reject, void) of one claim, or deferring an OPEN one until the
123	  // date typed on its row, or adding a proof to it, or reminding an OPEN or PENDING one (once per sheet-today), or splitting the amount typed on its row off an OPEN one
124	  // (a new OPEN claim listed under the person), or re-dating an OPEN or PENDING one to the date typed on its row;
125	  // a refusal shows on that claim's row.
126	  const action = useMutation({
127	    mutationFn: (a: { id: number; action: ClaimAction; reason: string; until: string; amount: string; date: string }) =>
128	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${a.id}/${a.action}`, { reason: a.reason, until: a.until, amount: a.amount, date: a.date }),
129	    onSuccess: (_, a) => {
130	      if (a.action === 'reject') setReasons((r) => ({ ...r, [a.id]: '' }));
131	      if (a.action === 'defer') setDeferDates((d) => ({ ...d, [a.id]: '' }));
132	      if (a.action === 'split') setSplitAmounts((m) => ({ ...m, [a.id]: '' }));
133	      if (a.action === 'redate') setNewDates((d) => ({ ...d, [a.id]: '' }));
134	    },
135	    onSettled: async () => {
136	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
137	    },
138	  });
139	
140	  // A steward moves a DRAFT, OPEN or PENDING claim to the person chosen on its row; a refusal shows on that claim's row.
141	  const reassign = useMutation({
142	    mutationFn: (r: { id: number; personId: number | null }) =>
143	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/reassign`, { claimId: r.id, personId: r.personId }),
144	    onSuccess: (_, r) => setTargets((t) => ({ ...t, [r.id]: '' })),
145	    onSettled: async () => {
146	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
147	    },
148	  });
149	
150	  const move = (id: number) => {
151	    setRefused(null);
152	    action.reset();
153	    reassign.reset();
154	    const target = targets[id] ?? '';
155	    reassign.mutate({ id, personId: target === '' ? null : Number(target) });
156	  };
157	
158	  const act = (id: number, a: ClaimAction) => {
159	    setRefused(null);
160	    action.reset();
161	    reassign.reset();
162	    action.mutate({
163	      id,
164	      action: a,
165	      reason: a === 'reject' ? reasons[id] ?? '' : '',
166	      until: a === 'defer' ? (deferDates[id] ?? '').trim() : '',
167	      amount: a === 'split' ? (splitAmounts[id] ?? '').trim() : '',
168	      date: a === 'redate' ? (newDates[id] ?? '').trim() : '',
169	    });
170	  };
171	
172	  // Only a DRAFT outside a closed period (the one containing its due-by), not locked by another user, can be edited, and not by a viewer: editing
173	  // any other claim is refused on its row, opens no editor and takes no lock (to change an open claim, void it and
174	  // add a new one). What this screen already knows is refused at once; the server refuses the rest, and the editor
175	  // then goes back to what it was.
176	  const openEditor = (c: Claim) => {
177	    save.reset();
178	    action.reset();
179	    reassign.reset();
180	    lock.reset();
181	    const role = settings?.roles.find((r) => r.user === user)?.role;
182	    const known =
183	      sheet?.archived ? 'the sheet is archived'
184	      : role === 'viewer' ? 'a viewer can change nothing'
185	      : c.status !== 'DRAFT' ? 'only a DRAFT claim can be edited'
186	      : periodOf(periods.data, c.dueBy)?.closed ? `the period ${periodOf(periods.data, c.dueBy)?.name} is closed`
187	      : c.lockedBy !== null && c.lockedBy !== user ? `the claim is being edited by ${c.lockedBy}`
188	      : null;
189	    if (known !== null) {
190	      setRefused({ id: c.id, message: known });
191	      return;
192	    }
193	    setRefused(null);
194	    const before = { editing, amount, date, note, corrects };
195	    fillForm(c);
196	    lock.mutate(
197	      { id: c.id, action: 'lock' },
198	      {
199	        onError: (e) => {
200	          setRefused({ id: c.id, message: e.message });
201	          setEditing(before.editing);
202	          setAmount(before.amount);
203	          setDate(before.date);
204	          setNote(before.note);
205	          setCorrects(before.corrects);
206	        },
207	      },
208	    );
209	  };
210	
211	  const cancel = () => {
212	    save.reset();
213	    if (editing !== null) {
214	      markLock(editing, null);
215	      lock.mutate({ id: editing, action: 'unlock' });
216	    }
217	    clearForm();
218	  };
219	
220	  // A claim of this person whose lock this user still holds (after the sheet is re-loaded) shows its editor open.
221	  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
222	  const held = mine.find((c) => c.status === 'DRAFT' && c.lockedBy !== null && c.lockedBy === user);
223	  useEffect(() => {
224	    if (editing === null && held !== undefined && !lock.isPending) fillForm(held);
225	    // eslint-disable-next-line react-hooks/exhaustive-deps
226	  }, [held?.id, editing, lock.isPending]);
227	
228	  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
229	    set(e.target.value);
230	    save.reset();
231	  };
232	
233	  // A claim's due: the one fixed when it was settled, else the greater of the floor in force on its date and its
234	  // figure (the rate figure its last statement bound it to, else its amount at the rate in force on its date for the
235	  // grade its person had on that date; 'n/a' when none applies) plus its late charge while it is overdue.
236	  const person = people.data?.find((p) => p.id === personId);
237	
238	  return (
239	    <tr>
240	      <td colSpan={PERSON_ROW_SPAN}>
241	        <form
242	          data-testid="claim-form"
243	          onSubmit={(e) => {
244	            e.preventDefault();
245	            setRefused(null);
246	            submitOnce(() => {
247	              save.reset();
248	              return save.mutateAsync({ id: editing, amount, date, note, corrects });
249	            });
250	          }}
251	        >
252	          <label>
253	            Amount <input data-testid="claim-form-amount" inputMode="decimal" value={amount} onChange={field(setAmount)} />
254	          </label>{' '}
255	          <label>
256	            Date{' '}
257	            <input
258	              type="text"
259	              placeholder="yyyy-mm-dd"
260	              data-testid="claim-form-date"
261	              value={date}
262	              onChange={field(setDate)}
263	            />
264	          </label>{' '}
265	          <label>
266	            Note <input data-testid="claim-form-note" value={note} onChange={field(setNote)} />
267	          </label>{' '}
268	          <label>
269	            Corrects{' '}
270	            <input
271	              data-testid="claim-form-corrects"
272	              inputMode="numeric"
273	              placeholder="claim no."
274	              value={corrects}
275	              onChange={field(setCorrects)}
276	            />
277	          </label>{' '}
278	          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending || (lock.isPending && lock.variables?.action === 'lock')}>
279	            {editing === null ? 'Add claim' : 'Save claim'}
280	          </button>
281	          {save.isError && <p data-testid="claim-form-error">{save.error.message}</p>}
282	        </form>
283	        <table data-testid="claims-list">
284	          <tbody>
285	            {mine.map((c) => (
286	              <tr key={c.id} data-testid={`claim-row-${c.id}`}>
287	                <td>
288	                  <input
289	                    type="checkbox"
290	                    data-testid="claim-select"
291	                    checked={selection.ids.has(c.id)}
292	                    onChange={(e) => selection.toggle(c.id, e.target.checked)}
293	                  />
294	                </td>
295	                <td data-testid="claim-number">{c.number ?? ''}</td>
296	                <td data-testid="claim-amount">{c.amount}</td>
297	                <td data-testid="claim-date">{c.date}</td>
298	                <td data-testid="claim-period">{periodOf(periods.data, c.dueBy)?.name ?? ''}</td>
299	                <td data-testid="claim-note">{c.note}</td>
300	                <td data-testid="claim-due">
301	                  {claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(person, c.date), c.date), settings, today, gradeOn(person, c.date))}
302	                </td>
303	                <td data-testid="claim-due-by">{c.dueBy}</td>
304	                <td data-testid="claim-overdue">
305	                  {today === undefined ? '' : isOverdue(c, today, settings, gradeOn(person, c.date)) ? 'yes' : 'no'}
306	                </td>
307	                <td data-testid="claim-corrects">{c.corrects ?? ''}</td>
308	                <td data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</td>
309	                <td data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</td>
310	                <td data-testid="claim-status">{c.status}</td>
311	                <td data-testid="claim-opened-by">{c.openedBy ?? ''}</td>
312	                <td data-testid="claim-proofs">{c.proofs}</td>
313	                <td data-testid="claim-reminded">{c.reminded ?? ''}</td>
314	                <td data-testid="claim-split-from">{c.splitFrom ?? ''}</td>
315	                <td data-testid="claim-deferred">{isDeferred(c, today) ? 'yes' : 'no'}</td>
316	                <td data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</td>
317	                <td data-testid="claim-log">
318	                  {c.log.map((line, i) => (
319	                    <div key={i} data-testid="claim-log-line">
320	                      {line}
321	                    </div>
322	                  ))}
323	                </td>
324	                <td>
325	                  <input
326	                    data-testid="claim-reject-reason"
327	                    placeholder="reject reason"
328	                    value={reasons[c.id] ?? ''}
329	                    onChange={(e) => {
330	                      const v = e.target.value;
331	                      setReasons((r) => ({ ...r, [c.id]: v }));
332	                    }}
333	                  />{' '}
334	                  {ACTIONS.map(([a, label]) => (
335	                    <button
336	                      key={a}
337	                      type="button"
338	                      data-testid={`claim-${a}`}
339	                      disabled={action.isPending}
340	                      onClick={() => act(c.id, a)}
341	                    >
342	                      {label}
343	                    </button>
344	                  ))}
345	                  <button
346	                    type="button"
347	                    data-testid="claim-proof"
348	                    disabled={action.isPending}
349	                    onClick={() => act(c.id, 'proof')}
350	                  >
351	                    Add proof
352	                  </button>{' '}
353	                  <button
354	                    type="button"
355	                    data-testid="claim-remind"
356	                    disabled={action.isPending}
357	                    onClick={() => act(c.id, 'remind')}
358	                  >
359	                    Remind
360	                  </button>{' '}
361	                  <input
362	                    type="text"
363	                    data-testid="claim-defer-date"
364	                    placeholder="defer until yyyy-mm-dd"
365	                    value={deferDates[c.id] ?? ''}
366	                    onChange={(e) => {
367	                      const v = e.target.value;
368	                      setDeferDates((d) => ({ ...d, [c.id]: v }));
369	                      if (action.variables?.id === c.id) action.reset();
370	                    }}
371	                  />{' '}
372	                  <button
373	                    type="button"
374	                    data-testid="claim-defer"
375	                    disabled={action.isPending}
376	                    onClick={() => act(c.id, 'defer')}
377	                  >
378	                    Defer
379	                  </button>{' '}
380	                  <input
381	                    data-testid="claim-split-amount"
382	                    inputMode="decimal"
383	                    placeholder="split off amount"
384	                    value={splitAmounts[c.id] ?? ''}
385	                    onChange={(e) => {
386	                      const v = e.target.value;
387	                      setSplitAmounts((m) => ({ ...m, [c.id]: v }));
388	                      if (action.variables?.id === c.id) action.reset();
389	                    }}
390	                  />{' '}
391	                  <button
392	                    type="button"
393	                    data-testid="claim-split"
394	                    disabled={action.isPending}
395	                    onClick={() => act(c.id, 'split')}
396	                  >
397	                    Split
398	                  </button>{' '}
399	                  <input
400	                    type="text"
401	                    data-testid="claim-date-new"
402	                    placeholder="new date yyyy-mm-dd"
403	                    value={newDates[c.id] ?? ''}
404	                    onChange={(e) => {
405	                      const v = e.target.value;
406	                      setNewDates((d) => ({ ...d, [c.id]: v }));
407	                      if (action.variables?.id === c.id) action.reset();
408	                    }}
409	                  />{' '}
410	                  <button
411	                    type="button"
412	                    data-testid="claim-redate"
413	                    disabled={action.isPending}
414	                    onClick={() => act(c.id, 'redate')}
415	                  >
416	                    Re-date
417	                  </button>{' '}
418	                  <select
419	                    data-testid="claim-reassign-to"
420	                    value={targets[c.id] ?? ''}
421	                    onChange={(e) => {
422	                      const v = e.target.value;
423	                      setTargets((t) => ({ ...t, [c.id]: v }));
424	                    }}
425	                  >
426	                    <option value="">move to…</option>
427	                    {(people.data ?? [])
428	                      .filter((p) => p.id !== personId)
429	                      .map((p) => (
430	                        <option key={p.id} value={String(p.id)}>
431	                          {p.name}
432	                        </option>
433	                      ))}
434	                  </select>{' '}
435	                  <button
436	                    type="button"
437	                    data-testid="claim-reassign"
438	                    disabled={reassign.isPending}
439	                    onClick={() => move(c.id)}
440	                  >
441	                    Reassign
442	                  </button>
443	                  {reassign.isError && reassign.variables?.id === c.id && (
444	                    <span data-testid="claim-error">{reassign.error.message}</span>
445	                  )}
446	                  {action.isError && action.variables?.id === c.id && (
447	                    <span data-testid="claim-error">{action.error.message}</span>
448	                  )}
449	                  {refused?.id === c.id && <span data-testid="claim-error">{refused.message}</span>}
450	                </td>
451	                <td>
452	                  {editing === c.id ? (
453	                    <button type="button" data-testid="claim-cancel" onClick={cancel}>
454	                      Cancel
455	                    </button>
456	                  ) : (
457	                    <button type="button" data-testid="claim-edit" onClick={() => openEditor(c)}>
458	                      Edit
459	                    </button>
460	                  )}
461	                </td>
462	              </tr>
463	            ))}
464	          </tbody>
465	        </table>
466	        {claims.isError && <p data-testid="claims-error">{claims.error.message}</p>}
467	      </td>
468	    </tr>
469	  );
470	}
