472	/** Open the selected claims together: the server opens, in list order, each that can be opened and
473	 *  leaves the rest; the bar shows how many were opened and how many refused (gone while it runs). */
474	function BulkOpen({ sheetId }: { sheetId: string }) {
475	  const selection = useClaimSelection(sheetId);
476	  const queryClient = useQueryClient();
477	  const submitOnce = useSingleFlight();
478	  const bulk = useMutation({
479	    mutationFn: (claimIds: number[]) =>
480	      postJson<{ opened: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-open`, { claimIds }),
481	    onSuccess: () => selection.clear(),
482	    onSettled: async () => {
483	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
484	    },
485	  });
486	  return (
487	    <p data-testid="bulk-open-bar">
488	      <button
489	        type="button"
490	        data-testid="bulk-open"
491	        disabled={bulk.isPending}
492	        onClick={() =>
493	          submitOnce(() => {
494	            bulk.reset();
495	            return bulk.mutateAsync([...selection.ids]);
496	          })
497	        }
498	      >
499	        Open selected ({selection.ids.size})
500	      </button>
501	      {bulk.isSuccess && (
502	        <>
503	          {' '}
504	          Opened <strong data-testid="bulk-opened">{bulk.data.opened}</strong>, refused{' '}
505	          <strong data-testid="bulk-refused">{bulk.data.refused}</strong>
506	        </>
507	      )}
508	      {bulk.isError && <span data-testid="bulk-open-error">{bulk.error.message}</span>}
509	    </p>
510	  );
511	}
