513	/** Settle the selected claims together: the server settles, in list order and by the rules of a single
514	 *  settle, each that can be settled (one sent to PENDING counts) and leaves the rest; the bar shows how
515	 *  many were settled and how many refused (gone while it runs). */
516	function BulkSettle({ sheetId }: { sheetId: string }) {
517	  const selection = useClaimSelection(sheetId);
518	  const queryClient = useQueryClient();
519	  const submitOnce = useSingleFlight();
520	  const bulk = useMutation({
521	    mutationFn: (claimIds: number[]) =>
522	      postJson<{ settled: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-settle`, { claimIds }),
523	    onSuccess: () => selection.clear(),
524	    onSettled: async () => {
525	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
526	    },
527	  });
528	  return (
529	    <p data-testid="bulk-settle-bar">
530	      <button
531	        type="button"
532	        data-testid="bulk-settle"
533	        disabled={bulk.isPending}
534	        onClick={() =>
535	          submitOnce(() => {
536	            bulk.reset();
537	            return bulk.mutateAsync([...selection.ids]);
538	          })
539	        }
540	      >
541	        Settle selected ({selection.ids.size})
542	      </button>
543	      {bulk.isSuccess && (
544	        <>
545	          {' '}
546	          Settled <strong data-testid="bulk-settled">{bulk.data.settled}</strong>, refused{' '}
547	          <strong data-testid="bulk-settle-refused">{bulk.data.refused}</strong>
548	        </>
549	      )}
550	      {bulk.isError && <span data-testid="bulk-settle-error">{bulk.error.message}</span>}
551	    </p>
552	  );
553	}
554	
555	/** The sheet's claimed-total: everyone's claimed added up. */
556	function ClaimedTotal({ sheetId }: { sheetId: string }) {
557	  const claims = useClaims(sheetId);
558	  const people = usePeople(sheetId);
559	  const today = useSheetToday(sheetId).data?.today;
560	  return (
561	    <p>
562	      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims.data ?? [], holdsById(people.data, today), today)}</strong>
563	    </p>
564	  );
565	}
566	
567	export const contributions = [
568	  PersonColumnHead.fill({ order: 10, Component: () => <th>Claimed</th> }),
569	  PersonCells.fill({ order: 10, Component: PersonClaimed }),
570	  PersonDetail.fill({ order: 10, Component: PersonClaims }),
571	  SheetBody.fill({ order: 15, Component: BulkOpen }),
572	  SheetBody.fill({ order: 16, Component: BulkSettle }),
573	  SheetBody.fill({ order: 20, Component: ({ sheetId }) => <ClaimedTotal sheetId={sheetId} /> }),
574	];
